settings.custom_css:
/* ===== Venus Flower Club - generated by _build/make-subscribers-page.mjs ===== */
selector{--padding-top:0px;--padding-right:20px;--padding-bottom:0px;--padding-left:20px;background:#FFFBE9;color:#141414;direction:rtl;font-family:var(--e-global-typography-vnsbody-font-family),"Discovery Fs",system-ui,sans-serif}
selector .fc,selector .fc p,selector .fc span,selector .fc div,selector .fc a,selector .fc sup{font-family:var(--e-global-typography-vnsbody-font-family),"Discovery Fs",system-ui,sans-serif}
selector .fc h1,selector .fc h2,selector .fc h3{font-family:var(--e-global-typography-vnsheading-font-family),"Leon","Discovery Fs",system-ui,sans-serif}
selector .fc{max-width:1180px;margin:0 auto;padding:64px 0 80px;text-align:center}
selector .fc-eyebrow{display:block;font-size:15px;font-weight:500;letter-spacing:.28em;color:var(--e-global-color-vnsgreen,#3A4831)}
selector .fc-title{margin:18px 0 0;font-family:var(--e-global-typography-vnsheading-font-family),"Leon","Discovery Fs",system-ui,sans-serif;font-weight:700;font-size:64px;line-height:1.08;color:#141414}
selector .fc-lead{max-width:720px;margin:22px auto 0;font-size:21px;line-height:1.5}
selector .fc-lead+.fc-lead{margin-top:14px}
selector .fc-sub{margin:64px 0 0;font-family:var(--e-global-typography-vnsheading-font-family),"Leon","Discovery Fs",system-ui,sans-serif;font-weight:700;font-size:34px;line-height:1.15;color:#141414}
selector .fc-plans{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;margin-top:32px}
selector .fc-plan{display:flex;flex-direction:column;background:#fff;border:1px solid rgba(20,20,20,.18);border-radius:12px;overflow:hidden;transition:transform .25s ease,box-shadow .25s ease}
selector .fc-plan:hover{transform:translateY(-4px);box-shadow:0 14px 34px rgba(20,20,20,.1)}
selector .fc-img{aspect-ratio:4/5;overflow:hidden;background:#F3E3C8}
selector .fc-img img{display:block;width:100%;height:100%;object-fit:cover;object-position:50% 40%;transition:transform .6s ease}
selector .fc-plan:hover .fc-img img{transform:scale(1.04)}
selector .fc-body{display:flex;flex:1;flex-direction:column;align-items:center;gap:6px;padding:26px 24px 28px}
selector .fc-en{font-size:14px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--e-global-color-vnsgreen,#3A4831)}
selector .fc-he{margin:0;font-family:var(--e-global-typography-vnsheading-font-family),"Leon","Discovery Fs",system-ui,sans-serif;font-weight:700;font-size:28px;line-height:1.15;color:#141414;white-space:nowrap}
selector .fc-price{margin:8px 0 20px;font-weight:500;font-size:44px;line-height:1;color:#141414;direction:ltr;unicode-bidi:isolate}
selector .fc-price sup{position:static;top:auto;font-size:.45em;line-height:0;vertical-align:super;margin-left:2px}
selector .fc-cta{box-sizing:border-box;margin-top:auto;width:100%;height:52px;display:flex;align-items:center;justify-content:center;border-radius:12px;background:var(--e-global-color-vnsgreen,#3A4831);color:#fff!important;font-size:17px;font-weight:500;text-decoration:none;transition:background .15s}
selector .fc-cta:hover{background:#2C3624}
selector .fc-cta:focus-visible{outline:3px solid #141414;outline-offset:2px}
selector .fc-note{margin:24px 0 0;font-size:16px;color:rgba(20,20,20,.72)}
selector .fc-outro{margin:48px 0 0;font-family:var(--e-global-typography-vnsheading-font-family),"Leon","Discovery Fs",system-ui,sans-serif;font-weight:700;font-size:30px;line-height:1.2;color:var(--e-global-color-vnsgreen,#3A4831)}
@media(max-width:1024px){
selector .fc{padding:48px 0 64px}
selector .fc-title{font-size:48px}
selector .fc-plans{gap:16px}
selector .fc-he{font-size:clamp(17px,2.5vw,23px)}
selector .fc-price{font-size:38px}
selector .fc-body{padding:20px 16px 22px}
}
@media(max-width:767px){
selector .fc{padding:36px 0 48px}
selector .fc-title{font-size:34px}
selector .fc-lead{font-size:18px}
selector .fc-sub{margin-top:44px;font-size:28px}
selector .fc-plans{grid-template-columns:1fr;max-width:440px;margin-inline:auto}
selector .fc-img{aspect-ratio:4/3}
selector .fc-he{font-size:24px}
selector .fc-outro{margin-top:36px;font-size:24px}
}
